print("pares verificados:", sum(len(pat.findall(open(fn,encoding='utf-8').read())) for fn in files), "| erros:", errs)
print("--- B) referências normativas")
ref=re.compile(r"art[s]?\.\s*[0-9][0-9.,;º§\s\w\-]*?(?=,|\s\(|\s—|\s\)|\.|\s[eE]\s|\s(de|da|do)\b|$)|art\.\s*[0-9.]+(?:,\s*§+\s*[0-9º]+)?|Lei\s*\d{1,5}/\d{4}|Lei\s+11\.419|13\.105/2015")
arts=set(); leis=set()
for fn in files:
    t=open(fn,encoding="utf-8").read()
    for m in re.finditer(r"arts?\.\s*([0-9][0-9.]{0,6})(?:,?\s*(?:§+\s*[0-9º]+|caput|inc\.?\s*[IVXLC]+|III|VII))?", t): arts.add(m.group(1))
    for m in re.finditer(r"Lei\s+(\d{3,6}/\d{4})", t): leis.add(m.group(1))
    for m in re.finditer(r"(?:Lei|lei)\s+(11\.419)(?:/2006)?", t): leis.add("11.419/2006")
print("arts citados:", sorted(arts)); print("leis citadas:", sorted(leis))
allowed_art={"219","220","224","229","231","335","1.003","1.023","1.026","4","231"}
print("arts FORA da biblioteca:", sorted(a for a in arts if a not in allowed_art))
allowed_lei={"11.419/2006","14.759/2023","13.105/2015"}
print("leis FORA da biblioteca:", sorted(l for l in leis if l not in allowed_lei))
print("--- C) alegações específicas")
m=open("memoria.md",encoding="utf-8").read()+ "".join(open(fn,encoding="utf-8").read() for fn in ["STATUS.md","QUESTIONS.md"])
d0712=dt.date(2026,12,7)
print("2026-12-07 dia da semana real:", ["seg","ter","qua","qui","sex","sáb","dom"][d0712.weekday()])
print("ocorrências '07/12/2026':", m.count("07/12/2026"))
for mm in re.finditer(r".{60}07/12/2026.{60}", m): print("  …", mm.group(0).replace("\n"," "), "…")
print("menções '13.925':", m.count("13.925"), "| 'art. 220, caput':", len(re.findall(r"220,\s*caput", m)), "| '220, §':", len(re.findall(r"220,\s*§", m)))
PY

