wd={"seg":0,"ter":1,"qua":2,"qui":3,"sex":4,"sáb":5,"sab":5,"dom":6}
pat=re.compile(r"(\d{2})/(\d{2})/(\d{4})\s*\((seg|ter|qua|qui|sex|sáb|sab|dom)")
errs=0; tot=0
for fn in files:
    for m in pat.finditer(open(fn,encoding="utf-8").read()):
        tot+=1
        d=dt.date(int(m.group(3)),int(m.group(2)),int(m.group(1)))
        if d.weekday()!=wd[m.group(4)]: print("ERRO",fn,m.group(0)); errs+=1
print("A) pares data×diasemana:",tot,"erros:",errs)
# claims: no stale 'domingo' tied to 07/12; list all 'domingo' mentions
