# weekday of key dates asserted in prose
for s in ["2026-12-07","2026-12-16","2027-02-15","2027-02-05","2026-12-15"]:
    d=dt.date.fromisoformat(s); print("B)",s,["seg","ter","qua","qui","sex","sáb","dom"][d.weekday()])
# C) normative refs again
arts=set(); 
for fn in files:
    t=open(fn,encoding="utf-8").read()
    for m in re.finditer(r"arts?\.\s*([0-9][0-9.]{0,6})",t): arts.add(m.group(1))
allowed={"219","220","224","229","231","335","1.003","1.023","1.026","4"}
print("C) arts citados:",sorted(arts),"| fora:",sorted(arts-allowed))
print("   '13.925' presente?:", any("13.925" in open(fn,encoding="utf-8").read() for fn in files))
# D) json
j=json.load(open("prazos.json",encoding="utf-8")); print("D) json ok:", j["citacao"]["contestacao_vencimento"], j["sentenca"]["embargos_vencimento"], j["sentenca"]["apelacao_vencimento"], "| dobro:", j["citacao"]["prazo_em_dobro"])
